-- 060: private commercial preparation. No operational tenant, trial or billing side effects.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create table private.studio_segments (
 id text primary key check(id~'^[a-z][a-z0-9-]{1,60}$'),name text not null check(length(name)between 2 and 120),
 model jsonb not null,revision integer not null default 1,updated_by uuid references public.profiles(id),updated_at timestamptz not null default clock_timestamp()
);
create table private.studio_drafts (
 id uuid primary key,owner_id uuid not null references public.profiles(id),name text not null check(length(btrim(name))between 2 and 160),
 segment_id text references private.studio_segments(id),configuration jsonb not null,revision integer not null default 1,
 state text not null default 'draft' check(state in('draft','converting','converted','deleted')),demo_id uuid unique references private.commercial_demos(id),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp()
);
create table private.studio_assets (
 id uuid primary key,draft_id uuid not null references private.studio_drafts(id),owner_id uuid not null references public.profiles(id),
 object_path text not null unique,metadata jsonb,state text not null default 'pending' check(state in('pending','ready','deleting','deleted')),
 created_at timestamptz not null default clock_timestamp()
);
create table private.studio_events (
 id uuid primary key default gen_random_uuid(),draft_id uuid references private.studio_drafts(id),actor_id uuid not null references public.profiles(id),
 event text not null,created_at timestamptz not null default clock_timestamp()
);
do $$declare t text;begin foreach t in array array['studio_segments','studio_drafts','studio_assets','studio_events']loop
 execute format('alter table private.%I enable row level security',t);execute format('alter table private.%I force row level security',t);
 execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);
end loop;end;$$;
-- Only checked SECURITY DEFINER entry points have table access; no direct client writes.
create function private.studio_require(p_id uuid)returns private.studio_drafts language plpgsql security definer set search_path='' as $$declare d private.studio_drafts;begin
 perform private.commercial_require('commercial.manage');select *into d from private.studio_drafts where id=p_id for update;
 if d.id is null or d.state='deleted' then raise exception 'commercial_studio_not_found';end if;
 if d.owner_id<>auth.uid()and not private.people_root(auth.uid())then raise exception 'access_denied'using errcode='42501';end if;return d;
end;$$;
create function public.commercial_studio(p_action text,p_data jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$
declare d private.studio_drafts;v private.studio_drafts;a private.studio_assets;r jsonb;cfg jsonb;row_ jsonb;id_ uuid;begin
 perform private.commercial_require('commercial.manage');perform pg_advisory_xact_lock(734921560);
 if p_action='cleanup'then
  -- Tombstone under the same advisory lock as every save/duplicate. Never remove shared or converted assets.
  update private.studio_assets candidate_asset set state='deleting'where (candidate_asset.owner_id=auth.uid()or private.people_root(auth.uid()))and candidate_asset.state in('pending','ready')
   and exists(select 1 from private.studio_drafts source where source.id=candidate_asset.draft_id and source.demo_id is null and source.state='deleted')
   and not exists(select 1 from private.studio_drafts other where (other.state<>'deleted'or other.demo_id is not null)and exists(select 1 from jsonb_array_elements(coalesce(other.configuration->'tables'->'company_media','[]'))m where m->>'id'=candidate_asset.id::text));
  return coalesce((select jsonb_agg(jsonb_build_object('id',candidate_asset.id,'object_path',candidate_asset.object_path))from private.studio_assets candidate_asset where state='deleting'and(owner_id=auth.uid()or private.people_root(auth.uid()))),'[]');
 elsif p_action='list'then return jsonb_build_object('drafts',coalesce((select jsonb_agg(to_jsonb(s)-'configuration'order by updated_at desc)from private.studio_drafts s where state<>'deleted'and(owner_id=auth.uid()or private.people_root(auth.uid()))),'[]'),
 'segments',coalesce((select jsonb_agg(to_jsonb(s)order by name)from private.studio_segments s),'[]'),'can_edit_segments',private.people_root(auth.uid()));
 elsif p_action='segment-save'then
  if not private.people_root(auth.uid())then raise exception 'access_denied'using errcode='42501';end if;
  perform private.commercial_config_validate(p_data->'model');
  if coalesce(jsonb_array_length(p_data->'model'->'tables'->'company_media'),0)>0 then raise exception 'commercial_studio_segment_media';end if;
  if exists(select 1 from private.studio_segments where id=p_data->>'id')then
   update private.studio_segments set name=p_data->>'name',model=p_data->'model',revision=revision+1,updated_by=auth.uid(),updated_at=clock_timestamp()where id=p_data->>'id'and revision=(p_data->>'revision')::int;
   if not found then raise exception 'commercial_revision_conflict';end if;
  else insert into private.studio_segments(id,name,model,updated_by)values(p_data->>'id',p_data->>'name',p_data->'model',auth.uid());end if;
  insert into private.studio_events(actor_id,event)values(auth.uid(),'segment_saved');return jsonb_build_object('saved',true);
 elsif p_action='create'then
  id_=(p_data->>'id')::uuid;
  if exists(select 1 from private.studio_drafts where id=id_)then d=private.studio_require(id_);return to_jsonb(d);end if;
  cfg=p_data->'configuration';perform private.commercial_config_validate(cfg);
  if coalesce(jsonb_array_length(cfg->'tables'->'company_media'),0)>0 then raise exception 'commercial_media_invalid';end if;
  insert into private.studio_drafts(id,owner_id,name,segment_id,configuration)values(id_,auth.uid(),p_data->>'name',p_data->>'segment_id',cfg)returning *into d;
  insert into private.studio_events(draft_id,actor_id,event)values(d.id,auth.uid(),'created');return to_jsonb(d);
 end if;
 d=private.studio_require((p_data->>'id')::uuid);
 if p_action='get'then return to_jsonb(d);
 elsif p_action='asset-read'then
  select *into a from private.studio_assets where id=(p_data->>'asset_id')::uuid and state='ready'and(draft_id=d.id or exists(select 1 from jsonb_array_elements(coalesce(d.configuration->'tables'->'company_media','[]'))m where m->>'id'=studio_assets.id::text));
  if a.id is null then raise exception 'access_denied'using errcode='42501';end if;return to_jsonb(a);
 elsif p_action='asset-reserve'then
  if d.state<>'draft'then raise exception 'commercial_studio_locked';end if;
  if(select count(*)from private.studio_assets where draft_id=d.id and state in('pending','ready'))>=40 then raise exception 'commercial_media_limit';end if;
  id_=(p_data->>'asset_id')::uuid;
  insert into private.studio_assets(id,draft_id,owner_id,object_path)values(id_,d.id,auth.uid(),'studio/'||d.id::text||'/'||id_::text)returning *into a;return to_jsonb(a);
 end if;
 if p_action='approve'and d.demo_id is not null then return to_jsonb(d);end if;
 if d.revision is distinct from(p_data->>'revision')::int then raise exception 'commercial_revision_conflict';end if;
 if p_action='save'then
  if d.state<>'draft'then raise exception 'commercial_studio_locked';end if;
  cfg=p_data->'configuration';perform private.commercial_config_validate(cfg);
  for row_ in select value from jsonb_array_elements(coalesce(cfg->'tables'->'company_media','[]'))loop
   if not exists(select 1 from private.studio_assets where id=(row_->>'id')::uuid and state='ready'and metadata=row_ and(draft_id=d.id or exists(select 1 from jsonb_array_elements(coalesce(d.configuration->'tables'->'company_media','[]'))old where old->>'id'=row_->>'id')))then raise exception 'commercial_media_invalid';end if;
  end loop;
  update private.studio_drafts set name=p_data->>'name',configuration=cfg,revision=revision+1,updated_at=clock_timestamp()where id=d.id returning *into d;
 elsif p_action='duplicate'then
  if d.state='converting'then raise exception 'commercial_studio_locked';end if;
  id_=(p_data->>'new_id')::uuid;
  insert into private.studio_drafts(id,owner_id,name,segment_id,configuration)values(id_,auth.uid(),left(d.name||' — cópia',160),d.segment_id,d.configuration)returning *into d;
 elsif p_action='delete'then
  if d.state='converting'then raise exception 'commercial_studio_locked';end if;
  update private.studio_drafts set state='deleted',revision=revision+1,updated_at=clock_timestamp()where id=d.id returning *into d;
 elsif p_action='approve'then
  if d.demo_id is not null then return to_jsonb(d);end if;
  perform private.commercial_config_validate(d.configuration);
  if coalesce(jsonb_array_length(d.configuration->'tables'->'services'),0)=0 or length(coalesce(d.configuration->'tables'->'company_settings'->0->>'description',''))<10 then raise exception 'commercial_configuration_not_ready';end if;
  if p_data->>'reviewed'is distinct from'true'then raise exception 'commercial_review_required';end if;
  r=public.commercial_demo_save(null,0,d.id,null,d.name,null,null,clock_timestamp()+interval '30 days');
  perform public.commercial_demo_draft((r->>'id')::uuid,(r->>'revision')::int,d.configuration,false);
  update private.studio_drafts set demo_id=(r->>'id')::uuid,state='converting',revision=revision+1,updated_at=clock_timestamp()where id=d.id returning *into d;
 else raise exception 'commercial_invalid';end if;
 insert into private.studio_events(draft_id,actor_id,event)values(d.id,auth.uid(),p_action);return to_jsonb(d);
end;$$;
create function public.commercial_studio_asset_finish(p_id uuid,p_metadata jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare a private.studio_assets;begin
 select *into a from private.studio_assets where id=p_id for update;
 if a.id is null or a.state<>'pending' or p_metadata->>'object_path' is distinct from a.object_path or p_metadata->>'id'is distinct from a.id::text or p_metadata->>'state'<>'ready'or p_metadata->>'sha256'!~'^[a-f0-9]{64}$'then raise exception 'commercial_media_invalid';end if;
 update private.studio_assets set metadata=p_metadata,state='ready'where id=p_id;return p_metadata;
end;$$;
revoke all on function private.studio_require(uuid),public.commercial_studio(text,jsonb),public.commercial_studio_asset_finish(uuid,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.commercial_studio(text,jsonb)to authenticated;
grant execute on function public.commercial_studio_asset_finish(uuid,jsonb)to service_role;
create function public.commercial_studio_complete(p_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare d private.studio_drafts;begin
 select *into d from private.studio_drafts where id=p_id for update;
 if d.state='converted'then return to_jsonb(d);end if;
 if d.state is distinct from'converting'or d.demo_id is null then raise exception 'commercial_studio_locked';end if;
 update private.studio_drafts set state='converted',revision=revision+1,updated_at=clock_timestamp()where id=p_id returning *into d;
 insert into private.studio_events(draft_id,actor_id,event)values(d.id,d.owner_id,'converted');return to_jsonb(d);
end;$$;
revoke all on function public.commercial_studio_complete(uuid)from public,anon,authenticated,service_role;
grant execute on function public.commercial_studio_complete(uuid)to service_role;
create function public.commercial_studio_asset_deleted(p_id uuid)returns void language plpgsql security definer set search_path=''as $$begin
 update private.studio_assets set state='deleted'where id=p_id and state='deleting';
end;$$;
revoke all on function public.commercial_studio_asset_deleted(uuid)from public,anon,authenticated,service_role;
grant execute on function public.commercial_studio_asset_deleted(uuid)to service_role;
-- Link-only demonstration invitations do not assert email consent or identity.
-- Activation and every email-send guard retain the previous implementation.
alter table private.commercial_invites alter column email_hash drop not null;
alter function public.commercial_invite_for_contact(uuid,uuid,text,uuid,text,timestamptz)rename to commercial_invite_for_contact_pre060;
revoke all on function public.commercial_invite_for_contact_pre060(uuid,uuid,text,uuid,text,timestamptz)from public,anon,authenticated,service_role;
create function public.commercial_invite_for_contact(p_demo uuid,p_lead uuid,p_purpose text,p_id uuid,p_hash text,p_expires timestamptz)returns jsonb language plpgsql security definer set search_path=''as $$declare d private.commercial_demos;l private.acquisition_leads;begin
 if p_purpose is distinct from'demonstration'then return public.commercial_invite_for_contact_pre060(p_demo,p_lead,p_purpose,p_id,p_hash,p_expires);end if;
 perform pg_advisory_xact_lock(734921554);d=private.commercial_demo_require(p_demo,'commercial.manage');perform private.commercial_require('commercial.manage',p_lead);
 if d.state<>'available'or d.published_version_id is null or d.expires_at<=clock_timestamp()or p_expires<=clock_timestamp()or p_expires>d.expires_at or p_expires>clock_timestamp()+interval'30 days'then raise exception 'commercial_expired';end if;
 if not exists(select 1 from private.commercial_demo_contacts where demo_id=d.id and lead_id=p_lead)then raise exception 'commercial_contact_not_linked';end if;
 select *into l from private.acquisition_leads where id=p_lead;
 if exists(select 1 from private.commercial_contacts where lead_id=p_lead and stage in('not_interested','archived'))or exists(select 1 from private.commercial_suppressions where email_hash=encode(extensions.digest(lower(l.email),'sha256'),'hex'))then raise exception 'commercial_contact_not_authorized';end if;
 insert into private.commercial_invites(id,lead_id,demo_id,purpose,token_hash,generation,email_hash,expires_at,created_by,version_id)values(p_id,p_lead,d.id,p_purpose,p_hash,d.generation,case when l.email is null then null else encode(extensions.digest(lower(l.email),'sha256'),'hex')end,p_expires,auth.uid(),d.published_version_id);
 insert into private.commercial_contact_events(lead_id,actor_id,event)values(p_lead,auth.uid(),'link_issued');
 return jsonb_build_object('id',p_id,'lead_id',p_lead,'demo_id',d.id,'slug',d.slug,'company',(select name from private.commercial_versions where id=d.published_version_id),'expires_at',p_expires,'purpose',p_purpose);
end;$$;
revoke all on function public.commercial_invite_for_contact(uuid,uuid,text,uuid,text,timestamptz)from public,anon,authenticated,service_role;
grant execute on function public.commercial_invite_for_contact(uuid,uuid,text,uuid,text,timestamptz)to authenticated;
-- Presentation-only snapshot extension. The original authorization and status checks run first.
alter function public.consumer_document(text,text,text)rename to consumer_document_pre060;
revoke all on function public.consumer_document_pre060(text,text,text)from public,anon,authenticated,service_role;
create function public.consumer_document(p_code text,p_kind text,p_reference text)returns jsonb language plpgsql security definer set search_path=''as $$declare result jsonb;q public.quote_requests;customer_ text;professional_ text;begin
 result=public.consumer_document_pre060(p_code,p_kind,p_reference);
 select *into q from public.quote_requests where public_code=p_code;
 select name into customer_ from public.customers where id=q.customer_id and organization_id=q.organization_id;
 result=result||jsonb_build_object('customer',jsonb_build_object('name',customer_));
 if p_kind='appointment'then
  select p.display_name into professional_ from public.appointments a join public.profiles p on p.id=a.responsible_id where a.public_code=p_reference and a.request_id=q.id and a.organization_id=q.organization_id;
  result=jsonb_set(result,'{content}',result->'content'||jsonb_build_object('professional',professional_));
 end if;return result;
end;$$;
revoke all on function public.consumer_document(text,text,text)from public,anon,authenticated,service_role;
grant execute on function public.consumer_document(text,text,text)to authenticated;
